<script setup>
import { onMounted, ref } from 'vue';
import LoadingBlock from '../components/LoadingBlock.vue'; import PageHeading from '../components/PageHeading.vue'; import { api, apiMessage } from '../lib/api';
const year=ref(String(new Date().getFullYear())),data=ref(null),loading=ref(false),error=ref(''); const percent=(v)=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;
const load=async()=>{loading.value=true;error.value='';try{data.value=(await api.get('/workplan-performance/state/trends',{params:{year:year.value}})).data.data}catch(e){error.value=apiMessage(e)}finally{loading.value=false}};onMounted(load);
</script>
<template><PageHeading eyebrow="Performance management" title="State Performance Trends"><span class="civic-kicker">Independent period observations</span></PageHeading><div v-if="error" class="civic-error">{{error}}</div><section class="civic-workspace"><div class="civic-form-grid"><label class="civic-field"><span>Year</span><input v-model="year" type="number"></label><div class="civic-field"><span>&nbsp;</span><button class="civic-button civic-button-primary" :disabled="loading" @click="load">Apply</button></div></div><p>Q1–Q4 and Annual remain independent observations. No trend score, momentum, or average is calculated.</p></section><LoadingBlock v-if="loading"/><section v-else-if="data" class="civic-workspace"><div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>MDA</th><th v-for="period in data.periods" :key="period">{{period.toUpperCase()}}</th></tr></thead><tbody><tr v-for="mda in data.mdas" :key="mda.id"><td>{{mda.name}}</td><td v-for="period in data.periods" :key="period"><RouterLink v-if="mda.observations[period]?.workplan_id" :to="{path:'/workplan-performance',query:{workplan_id:mda.observations[period].workplan_id,period}}">{{percent(mda.observations[period].official_score)}}</RouterLink><template v-else>—</template><br><small v-if="mda.observations[period]">Rev {{mda.observations[period].revision_no ?? '—'}} · {{mda.observations[period].rank_status.replace('_',' ')}}</small></td></tr><tr v-if="!data.mdas.length"><td colspan="6">No Workplan observations for this year.</td></tr></tbody></table></div></section></template>
